-- MediVerse seed data — generated from src/data/hospitals.js and src/data/mock.js
-- Run AFTER schema.sql. Safe to re-run: every row upserts on its primary key.
--
-- 234 hospitals, 40 sample doctors.
-- Seeding happens here rather than from the app because RLS restricts writes
-- on these tables to admins — which is what we want at runtime, and why the
-- initial load belongs in the SQL editor.

on conflict (id) do update set
  name = excluded.name, state = excluded.state, city = excluded.city, area = excluded.area,
  address = excluded.address, phone = excluded.phone, emergency_phone = excluded.emergency_phone,
  email = excluded.email, website = excluded.website, doctors_url = excluded.doctors_url,
  verified = excluded.verified, note = excluded.note, updated_at = now();

on conflict (id) do update set
  name = excluded.name, specialty = excluded.specialty, state = excluded.state,
  experience = excluded.experience, qualifications = excluded.qualifications,
  hospital = excluded.hospital, languages = excluded.languages, fee = excluded.fee,
  rating = excluded.rating, status = excluded.status, next_slot = excluded.next_slot,
  featured = excluded.featured, nationwide = excluded.nationwide, updated_at = now();
